const queries = [
  { q: 'مسلسل مدبلج', origin: 'other',   category: 'drama',   lang: 'ar_dubbed' },
  { q: 'فيلم عربي',   origin: 'moroccan', category: 'drama',   lang: 'ar' },
  { q: 'film marocain complet', origin: 'moroccan', category: 'drama', lang: 'ar' },
  { q: 'مسلسل تركي مدبلج', origin: 'turkish', category: 'drama', lang: 'ar_dubbed' },
  { q: 'مسلسل هندي مدبلج', origin: 'indian',  category: 'drama', lang: 'ar_dubbed' }
];
return queries.map(q => ({ json: q }));

const body = $input.first().json;
const query = $('DM Queries').item.json;
const list = body?.list || [];

const MIN_DUR = 900;

const candidates = list
  .filter(v => v.allow_embed && v.status === 'published' && (v.duration || 0) >= MIN_DUR)
  .map(v => {
    const isFilm = (v.duration || 0) >= 2100;
    const year = v.created_time ? new Date(v.created_time * 1000).getFullYear() : null;
    return {
      platform: 'dailymotion',
      platform_id: v.id,
      title_raw: v.title || '',
      type: isFilm ? 'film' : 'episode',
      origin: query.origin || 'other',
      language: query.lang || 'ar_dubbed',
      category: query.category || 'drama',
      year,
      duration_sec: v.duration || null,
      poster_url: v.thumbnail_url || null,
      embed_url: v.embed_url || `https://www.dailymotion.com/embed/video/${v.id}`,
      embeddable: true,
      keyword: query.q,
      source_workflow: '04-dailymotion-discover'
    };
  });

console.log(`[DM] '${query.q}' → ${candidates.length} candidates`);
return [{ json: { candidates, query: query.q } }];
